                    <div class="data-row"><span class="label">ALUNO COM DEFICIÊNCIA?</span><span class="value">${o.condicoesFamiliares.alunoDeficiencia||"-"} ${o.condicoesFamiliares.qualDeficiencia?`(${o.condicoesFamiliares.qualDeficiencia})`:""}</span></div>
